package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.type.BasicType;
import java.io.*;
import java.lang.reflect.TypeVariable;
import java.math.*;
import java.util.*;
import java.util.HashMap;
import java.util.Map;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MapType.construct(Class, JavaType, JavaType)
 */
public class MapType_construct_TriageGen1Test {

    @Test
    public void testConstruct_Success() {
        // Arrange
        Class<?> rawType = Map.class;
        JavaType keyType = BasicType.fromString("java.lang.String");
        JavaType valueType = BasicType.fromString("java.lang.Integer");

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        Assert.assertNotNull("Result should not be null", result);
        Assert.assertEquals("Raw type should match", rawType, result.getRawClass());
        Assert.assertEquals("Key type should match", keyType, result.getKeyType());
        Assert.assertEquals("Value type should match", valueType, result.getValueType());

        // Verify toString contains class info to ensure object is initialized correctly
        String toString = result.toString();
        Assert.assertTrue("toString should contain raw class name", toString.contains("java.util.Map"));
    }

    @Test
    public void testConstruct_WithDifferentTypes() {
        // Arrange
        Class<?> rawType = HashMap.class;
        JavaType keyType = BasicType.fromString("java.lang.Long");
        JavaType valueType = BasicType.fromString("java.lang.Boolean");

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        Assert.assertNotNull(result);
        Assert.assertEquals(rawType, result.getRawClass());
        Assert.assertEquals(keyType, result.getKeyType());
        Assert.assertEquals(valueType, result.getValueType());
    }

    @Test
    public void testConstruct_NullKeyType() {
        // Arrange
        Class<?> rawType = Map.class;
        JavaType keyType = null;
        JavaType valueType = BasicType.fromString("java.lang.String");

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        Assert.assertNotNull(result);
        Assert.assertNull("Key type can be null per method signature", result.getKeyType());
        Assert.assertEquals(valueType, result.getValueType());
    }

    @Test
    public void testConstruct_NullValueType() {
        // Arrange
        Class<?> rawType = Map.class;
        JavaType keyType = BasicType.fromString("java.lang.String");
        JavaType valueType = null;

        // Act
        MapType result = MapType.construct(rawType, keyType, valueType);

        // Assert
        Assert.assertNotNull(result);
        Assert.assertEquals(keyType, result.getKeyType());
        Assert.assertNull("Value type can be null per method signature", result.getValueType());
    }

    @Test(expected = NullPointerException.class)
    public void testConstruct_NullRawType() {
        // Act
        // This should trigger NPE when accessing rawType.getTypeParameters()
        MapType.construct(null, BasicType.fromString("java.lang.String"), BasicType.fromString("java.lang.String"));
    }
}
